INSERT INTO history (id, record_kind, record_id, action, actor_user_id, effective_user_id, data, fictional, created_at)
SELECT 'migration:20261115010000_apply_client_review_decisions:' || c.id, 'client', c.id, CASE WHEN t.decision = 'Delete' THEN 'delete' WHEN ((t.decision = 'Active' AND c.archived_at IS NOT NULL) OR (t.decision = 'Archive' AND c.archived_at IS NULL)) THEN CASE WHEN t.decision = 'Active' THEN 'restore' ELSE 'archive' END ELSE 'review' END, 'support-admin', 'support-admin',
json_object('migration', '20261115010000_apply_client_review_decisions', 'sourceHash', '7251d677c12a09421426cac6a0c4c8e7f3aaa7227dd4df70429073c67fa96ab2', 'groupHash', 'b700d7a4dc9704aae0bbc4b3bc58c58449fc140472b3b9002b509055fbdd7420', 'group', t.review_group, 'decision', t.decision,
 'before', json_object('archivedAt', c.archived_at, 'revision', c.revision, 'updatedAt', c.updated_at),
 'after', CASE WHEN t.decision = 'Delete' THEN NULL ELSE json_object('archivedAt', CASE WHEN t.decision = 'Active' THEN NULL ELSE coalesce(c.archived_at, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) END, 'revision', c.revision + CASE WHEN ((t.decision = 'Active' AND c.archived_at IS NOT NULL) OR (t.decision = 'Archive' AND c.archived_at IS NULL)) THEN 1 ELSE 0 END, 'updatedAt', CASE WHEN ((t.decision = 'Active' AND c.archived_at IS NOT NULL) OR (t.decision = 'Archive' AND c.archived_at IS NULL)) THEN strftime('%Y-%m-%dT%H:%M:%fZ', 'now') ELSE c.updated_at END) END), c.fictional, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM clients c JOIN targets t ON t.id = c.id;

INSERT INTO mutation_guards (id, passed) SELECT '20261115010000_apply_client_review_decisions:history', CASE WHEN (SELECT count(*) FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client') IN (0, 684) THEN 1 ELSE 0 END;

INSERT INTO mutation_guards (id, passed) SELECT '20261115010000_apply_client_review_decisions:delete-links', CASE WHEN NOT EXISTS (SELECT 1 FROM opportunity_clients WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete')) AND NOT EXISTS (SELECT 1 FROM tasks WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete')) AND NOT EXISTS (SELECT 1 FROM clients WHERE referred_by_client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') AND id NOT IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete')) AND NOT EXISTS (SELECT 1 FROM client_relationships WHERE (client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') AND related_client_id NOT IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete')) OR (related_client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') AND client_id NOT IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete'))) AND NOT EXISTS (SELECT 1 FROM record_references WHERE target_client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') AND (client_id IS NULL OR client_id NOT IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete'))) THEN 1 ELSE 0 END;

INSERT INTO mutation_guards (id, passed) SELECT '20261115010000_apply_client_review_decisions:test-links', CASE WHEN NOT EXISTS (SELECT 1 FROM clients WHERE id GLOB 'import-client-*') OR ((SELECT count(*) FROM opportunities WHERE id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND revision = 5 AND archived_at IS NULL AND stage = 'new-lead') = 1 AND (SELECT count(*) FROM opportunity_clients WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f') = 1 AND EXISTS (SELECT 1 FROM opportunity_clients WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND client_id = 'import-client-303') AND NOT EXISTS (SELECT 1 FROM tasks WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f') AND NOT EXISTS (SELECT 1 FROM checklist_items WHERE checklist_id IN (SELECT id FROM stage_checklists WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f')) AND NOT EXISTS (SELECT 1 FROM checklist_progress WHERE checklist_id IN (SELECT id FROM stage_checklists WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f')) AND NOT EXISTS (SELECT 1 FROM record_references WHERE target_opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND (opportunity_id IS NULL OR opportunity_id <> 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f'))) THEN 1 ELSE 0 END;

INSERT INTO history (id, record_kind, record_id, action, actor_user_id, effective_user_id, data, fictional, created_at)
SELECT 'migration:20261115010000_apply_client_review_decisions:' || id, 'opportunity', id, 'delete', 'support-admin', 'support-admin', json_object('migration', '20261115010000_apply_client_review_decisions', 'sourceHash', '7251d677c12a09421426cac6a0c4c8e7f3aaa7227dd4df70429073c67fa96ab2', 'reason', 'Developer confirmed this was a test; archive its client and delete the opportunity.', 'before', json_object('revision', revision, 'updatedAt', updated_at, 'archivedAt', archived_at)), fictional, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM opportunities WHERE id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND EXISTS (SELECT 1 FROM history WHERE id = 'migration:20261115010000_apply_client_review_decisions:import-client-303');

UPDATE clients AS c SET archived_at = json_extract(h.data, '$.after.archivedAt'), revision = json_extract(h.data, '$.after.revision'), updated_at = json_extract(h.data, '$.after.updatedAt') FROM history h WHERE h.id = 'migration:20261115010000_apply_client_review_decisions:' || c.id AND json_extract(h.data, '$.decision') <> 'Delete' AND c.revision = json_extract(h.data, '$.before.revision') AND json_extract(h.data, '$.after.revision') > c.revision;

DELETE FROM record_references WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND EXISTS (SELECT 1 FROM history WHERE id = 'migration:20261115010000_apply_client_review_decisions:a2b8f3ee-f291-42d9-95e0-05b56f305a3f');

DELETE FROM opportunity_clients WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND EXISTS (SELECT 1 FROM history WHERE id = 'migration:20261115010000_apply_client_review_decisions:a2b8f3ee-f291-42d9-95e0-05b56f305a3f');

DELETE FROM stage_checklists WHERE opportunity_id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND EXISTS (SELECT 1 FROM history WHERE id = 'migration:20261115010000_apply_client_review_decisions:a2b8f3ee-f291-42d9-95e0-05b56f305a3f');

DELETE FROM opportunities WHERE id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND EXISTS (SELECT 1 FROM history WHERE id = 'migration:20261115010000_apply_client_review_decisions:a2b8f3ee-f291-42d9-95e0-05b56f305a3f' AND json_extract(data, '$.before.revision') = opportunities.revision);

DELETE FROM record_references WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM client_relationships WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') AND related_client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM person_phones WHERE person_id IN (SELECT id FROM client_people WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete'));

DELETE FROM person_emails WHERE person_id IN (SELECT id FROM client_people WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete'));

DELETE FROM client_people WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM client_addresses WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM client_key_dates WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM client_tags WHERE client_id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

DELETE FROM clients WHERE id IN (SELECT record_id FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete');

INSERT INTO mutation_guards (id, passed) SELECT '20261115010000_apply_client_review_decisions:deleted', CASE WHEN changes() = (SELECT count(*) FROM history WHERE json_extract(data, '$.migration') = '20261115010000_apply_client_review_decisions' AND record_kind = 'client' AND json_extract(data, '$.decision') = 'Delete') THEN 1 ELSE 0 END;

INSERT INTO mutation_guards (id, passed) SELECT '20261115010000_apply_client_review_decisions:states', CASE WHEN NOT EXISTS (SELECT 1 FROM history h LEFT JOIN clients c ON c.id = h.record_id WHERE json_extract(h.data, '$.migration') = '20261115010000_apply_client_review_decisions' AND h.record_kind = 'client' AND ((json_extract(h.data, '$.decision') = 'Delete' AND c.id IS NOT NULL) OR (json_extract(h.data, '$.decision') <> 'Delete' AND (c.id IS NULL OR c.archived_at IS NOT json_extract(h.data, '$.after.archivedAt') OR c.revision <> json_extract(h.data, '$.after.revision') OR c.updated_at <> json_extract(h.data, '$.after.updatedAt'))))) AND NOT EXISTS (SELECT 1 FROM opportunities WHERE id = 'a2b8f3ee-f291-42d9-95e0-05b56f305a3f') THEN 1 ELSE 0 END;

DELETE FROM mutation_guards WHERE id LIKE '20261115010000_apply_client_review_decisions:%';
